import { useState } from "react";
import { Button, Form } from "react-bootstrap";
import { useDispatch, useSelector } from "react-redux";
import { saveShippingAddress } from "../actions/cartActions";
import CheckoutSteps from "../components/CheckoutSteps";
import FormContainer from "../components/FormContainer";
import { useTranslation } from "react-i18next";

function ShippingScreen({ history }) {
  const cart = useSelector((state) => state.cart);
  const { shippingAddress } = cart;

  const dispatch = useDispatch();

  const [address, setAddress] = useState(shippingAddress.address);
  const [city, setCity] = useState(shippingAddress.city);
  const [postalCode, setPostalCode] = useState(shippingAddress.postalCode);
  const [country, setCountry] = useState(shippingAddress.country);

  const { t } = useTranslation();

  const submitHandler = (e) => {
    e.preventDefault();
    dispatch(saveShippingAddress({ address, city, postalCode, country }));
    history.push("/payment");
  };

  return (
    <FormContainer>
      <CheckoutSteps step1 step2 />
      <h1>{t("shippingScreen.title")}</h1>
      <Form onSubmit={submitHandler}>
        <Form.Group controlId="address">
          <Form.Label>{t("shippingScreen.address")}</Form.Label>
          <Form.Control
            required
            type="text"
            placeholder={t("shippingScreen.addressPlaceholder")}
            value={address ? address : ""}
            onChange={(e) => setAddress(e.target.value)}
          ></Form.Control>
        </Form.Group>

        <Form.Group controlId="city">
          <Form.Label>{t("shippingScreen.city")}</Form.Label>
          <Form.Control
            required
            type="text"
            placeholder={t("shippingScreen.cityPlaceholder")}
            value={city ? city : ""}
            onChange={(e) => setCity(e.target.value)}
          ></Form.Control>
        </Form.Group>

        <Form.Group controlId="postalCode">
          <Form.Label>{t("shippingScreen.postalCode")}</Form.Label>
          <Form.Control
            required
            type="text"
            placeholder={t("shippingScreen.postalCodePlaceholder")}
            value={postalCode ? postalCode : ""}
            onChange={(e) => setPostalCode(e.target.value)}
          ></Form.Control>
        </Form.Group>

        <Form.Group controlId="country">
          <Form.Label>{t("shippingScreen.country")}</Form.Label>
          <Form.Control
            required
            type="text"
            placeholder={t("shippingScreen.countryPlaceholder")}
            value={country ? country : ""}
            onChange={(e) => setCountry(e.target.value)}
          ></Form.Control>
        </Form.Group>

        <Button type="submit" variant="primary">
          {t("shippingScreen.continue")}
        </Button>
      </Form>
    </FormContainer>
  );
}

export default ShippingScreen;
